public interface IStockLedger
{
    void Record(string sku, int delta);

    int NetAdjustment(string sku);
}

/// <summary>In-memory <see cref="IStockLedger"/>.</summary>
public sealed class InMemoryStockLedger : IStockLedger
{
    private readonly Dictionary<string, int> _adjustments = new(StringComparer.Ordinal);

    public void Record(string sku, int delta)
        => _adjustments[sku] = _adjustments.TryGetValue(sku, out var v) ? v + delta : delta;

    public int NetAdjustment(string sku)
        => _adjustments.TryGetValue(sku, out var v) ? v : 0;
}
